const U32_MASK: u64 = 0xffff_ffff;
const U64_MASK: u128 = 0xffff_ffff_ffff_ffff;

#[derive(Clone)]
struct Entity {
    kind: String,
    pos: (i32, i32),
    health: i32,
}

#[derive(Clone)]
