#[derive(Clone)]
struct ChaCha8Rng {
    state: [u32; 16],
    buffer: Vec<u32>,
    index: usize,
}

impl ChaCha8Rng {
    fn new(seed: u64) -> Self {
        Self {
            state: chacha_seed_from_u64(seed),
            buffer: Vec::new(),
            index: 0,
        }
    }

    fn next_u32(&mut self) -> u32 {
        if self.index >= self.buffer.len() {
            self.buffer = self.refill4();
            self.index = 0;
        }
        let value = self.buffer[self.index];
        self.index += 1;
        value
    }

    fn random_f32(&mut self) -> f32 {
        ((self.next_u32() >> 8) as f32) * (1.0 / ((1u32 << 24) as f32))
    }

    fn gen_range_u32_inclusive(&mut self, low: u32, high: u32) -> u32 {
        sample_single_u32(self, low, high + 1)
    }

    fn refill4(&mut self) -> Vec<u32> {
        let mut out = Vec::with_capacity(64);
        let mut base = self.state;
        for _ in 0..4 {
            let mut block = base;
            for _ in 0..4 {
                chacha_double_round(&mut block);
            }
            for idx in 0..16 {
                out.push(block[idx].wrapping_add(base[idx]));
            }
            base[12] = base[12].wrapping_add(1);
            if base[12] == 0 {
                base[13] = base[13].wrapping_add(1);
            }
        }
        self.state[12] = base[12];
        self.state[13] = base[13];
        out
    }
}

fn sample_single_u32(rng: &mut ChaCha8Rng, low: u32, high: u32) -> u32 {
    let range = high - low;
    let zone = ((range as u64) << (32 - range.leading_zeros())) - 1;
    loop {
        let value = rng.next_u32() as u64;
        let product = value * range as u64;
        let hi = (product >> 32) as u32;
        let lo = (product & U32_MASK) as u32;
        if (lo as u64) <= (zone & U32_MASK) {
            return low + hi;
        }
    }
}

fn chacha_seed_from_u64(seed: u64) -> [u32; 16] {
    let mut state = seed as u128 & U64_MASK;
    let mut data = Vec::with_capacity(32);
    for _ in 0..8 {
        state = (state * 6364136223846793005u128 + 11634580027462260723u128) & U64_MASK;
        let xorshifted = (((state >> 18) ^ state) >> 27) as u32;
        let rot = ((state >> 59) & 31) as u32;
        let value = xorshifted.rotate_right(rot);
        data.extend_from_slice(&value.to_le_bytes());
    }
    let mut key = [0u32; 8];
    for i in 0..8 {
        key[i] = u32::from_le_bytes(data[i * 4..i * 4 + 4].try_into().unwrap());
    }
    [
        0x6170_7865,
        0x3320_646e,
        0x7962_2d32,
        0x6b20_6574,
        key[0],
        key[1],
        key[2],
        key[3],
        key[4],
        key[5],
        key[6],
        key[7],
        0,
        0,
        0,
        0,
    ]
}

fn chacha_double_round(s: &mut [u32; 16]) {
    quarter_round(s, 0, 4, 8, 12);
    quarter_round(s, 1, 5, 9, 13);
    quarter_round(s, 2, 6, 10, 14);
    quarter_round(s, 3, 7, 11, 15);
    quarter_round(s, 0, 5, 10, 15);
    quarter_round(s, 1, 6, 11, 12);
    quarter_round(s, 2, 7, 8, 13);
    quarter_round(s, 3, 4, 9, 14);
}

fn quarter_round(s: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
    s[a] = s[a].wrapping_add(s[b]);
    s[d] = (s[d] ^ s[a]).rotate_left(16);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_left(12);
    s[a] = s[a].wrapping_add(s[b]);
    s[d] = (s[d] ^ s[a]).rotate_left(8);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_left(7);
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let entry: Value = serde_json::from_str(&input).unwrap();
    let mut engine = Engine::reset(&entry);
    let actions = entry
        .get("actions")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let checkpoint_after = entry.get("checkpoint_after").and_then(Value::as_i64);
    let mut checkpoint: Option<Engine> = None;
    for (idx, action) in actions.iter().enumerate() {
        if engine.terminated || engine.truncated {
            break;
        }
        engine.step(action);
        if checkpoint_after == Some((idx + 1) as i64) {
            checkpoint = Some(engine.clone());
        }
    }
    if let Some(saved) = checkpoint {
        if let Some(restored) = entry.get("restore_then_actions").and_then(Value::as_array) {
            engine = saved;
            for action in restored {
                if engine.terminated || engine.truncated {
                    break;
                }
                engine.step(action);
            }
        }
    }
    println!("{}", json!({ "events": engine.events }));
}

impl Engine {
    fn reset(entry: &Value) -> Self {
        let task = scenario_to_task(entry);
        let scenario_id = task
            .get("scenario_id")
            .or_else(|| entry.get("scenario_id"))
            .or_else(|| task.get("task_id"))
            .and_then(Value::as_str)
            .unwrap_or("manual")
            .to_string();
        let world_doc = task.get("world").cloned().unwrap_or_else(|| json!({}));
        let rules = task
            .get("rules")
            .cloned()
            .unwrap_or_else(|| json!({"base":"no_homeostasis"}));
        let seed = world_doc
            .get("seed")
            .or_else(|| entry.get("seed"))
            .and_then(Value::as_i64)
            .unwrap_or(101) as u64;
        let use_default = world_doc
            .get("use_default")
            .and_then(Value::as_str)
            .unwrap_or("policy_dev_small");
        let width = world_doc.get("width").and_then(Value::as_i64).unwrap_or(
            if use_default == "craftax_partial_64" {
                64
            } else {
                32
            },
        ) as i32;
        let height = world_doc.get("height").and_then(Value::as_i64).unwrap_or(
            if use_default == "craftax_partial_64" {
                64
            } else {
                32
            },
        ) as i32;
        let max_steps = world_doc
            .get("max_steps")
            .and_then(Value::as_i64)
            .unwrap_or(1000) as i32;
        let checkpoint_every_n_steps = task
            .get("checkpoint_every_n_steps")
            .and_then(Value::as_i64)
            .unwrap_or(10) as i32;
        let config_hash = config_hash_for(&scenario_id, &task);
        let mut world = make_world(width, height, max_steps, seed, &world_doc);
        apply_adapter_hooks(&mut world, &rules);
        let private_achievements = world
            .achievements
            .iter()
            .filter_map(|(k, v)| if *v > 0 { Some(k.clone()) } else { None })
            .collect::<BTreeSet<_>>();
        let mut engine = Self {
            checkpoint_every_n_steps,
            rules,
            monty_reward: task.get("monty_reward").cloned(),
            world,
            events: Vec::new(),
            private_step_index: 0,
            terminated: false,
            truncated: false,
            done_reason: None,
            private_achievements,
            reward_last: 0.0,
            total_reward: 0.0,
            debug_events: Vec::new(),
        };
        engine
            .events
            .push(format!("TaskResolved({},{})", scenario_id, config_hash));
        engine
    }

    fn step(&mut self, raw_action: &Value) {
        let action = normalize_action(raw_action);
        if !ACTIONS.contains(&action.as_str()) {
            self.reject(&action, "unknown_action");
            return;
        }
        if self.terminated || self.truncated {
            self.reject(&action, "terminal");
            return;
        }
        let before_inventory = self.world.inventory.clone();
        let before_achievements = self.world.achievements.clone();
        let before_pos = self.world.player_pos;
        let before_facing = self.world.player_facing;
        let before_step = self.world.step;
        self.debug_events.clear();

        self.process_action(&action);
        self.world.step += 1;
        let done_reason = self.done_reason_now();
        if done_reason.as_deref() == Some("death") {
            self.debug_events.push("Death cause: unknown".to_string());
        }
        self.private_step_index = self.world.step;
        self.terminated = done_reason.as_deref() == Some("death");
        self.truncated = done_reason.as_deref() == Some("max_steps");
        self.done_reason = done_reason.clone();

        let after_inventory = self.world.inventory.clone();
        let newly_unlocked = newly_unlocked(&before_achievements, &self.world.achievements);
        let env_components = self.env_reward_components(&newly_unlocked, done_reason.as_deref());
        let monty_reward =
            self.monty_transition_reward(&before_inventory, &after_inventory, &newly_unlocked);
        self.apply_reward_deltas(&env_components, monty_reward);

        self.events.push(format!(
            "ActionApplied({},step={})",
            display_action(&action),
            self.private_step_index
        ));
        self.append_inventory_deltas(&action, &before_inventory, &after_inventory);
        if before_pos != self.world.player_pos || before_facing != self.world.player_facing {
            self.events.push(format!(
                "StateTransition(pos={},facing={})",
                py_list2(self.world.player_pos),
                py_list2(self.world.player_facing)
            ));
        } else if before_step != self.world.step && action == "__never__" {
            self.events.push(format!(
                "StateTransition(step={}->{})",
                before_step, self.world.step
            ));
        }
        for achievement in &newly_unlocked {
            self.private_achievements.insert(achievement.clone());
            self.events
                .push(format!("AchievementUnlocked({})", achievement));
        }
        for debug in &self.debug_events {
            self.events.push(format!("Debug({})", debug));
        }
        self.append_reward_delta_events(&env_components, monty_reward);
        if let Some(reason) = done_reason {
            let terminal = if reason == "death" {
                "Death"
            } else {
                "EpisodeTruncated"
            };
            self.events.push(format!("{}({})", terminal, reason));
            self.events.push(format!("Terminal({})", reason));
        }
        self.append_checkpoint_cadence_event();
    }

    fn reject(&mut self, action: &str, reason: &str) {
        self.events.push(format!(
            "ActionRejected({},{},step={})",
            action, reason, self.private_step_index
        ));
        if reason != "terminal" {
            self.events.push(format!("RuleViolation({})", reason));
        }
        let env_components = self.rejection_reward_components(reason);
        let monty = self.monty_rejection_reward(reason);
        self.apply_reward_deltas(&env_components, monty);
        self.append_reward_delta_events(&env_components, monty);
    }

    fn process_action(&mut self, action: &str) {
        if self.world.player_sleeping && action != "noop" && action != "sleep" {
            self.world.player_sleeping = false;
            return;
        }
        match action {
            "move_left" | "move_right" | "move_up" | "move_down" => self.move_player(action),
            "do" => self.do_action(),
            "sleep" => self.world.player_sleeping = true,
            a if a.starts_with("place_") => self.place(a),
            a if a.starts_with("make_") => self.craft(a),
            a if a.starts_with("drink_potion_") => {
                self.drink_potion(a.trim_start_matches("drink_potion_"))
            }
            _ => {}
        }
    }

    fn move_player(&mut self, action: &str) {
        let (dx, dy) = dir(action).unwrap();
        self.world.player_facing = (dx, dy);
        let target = (self.world.player_pos.0 + dx, self.world.player_pos.1 + dy);
        if !self.in_bounds(target)
            || !is_walkable(&self.tile(target))
            || self.entity_at(target).is_some()
        {
            return;
        }
        self.world.player_pos = target;
        if self.tile(target) == "lava" {
            self.world.last_damage_source = Some("lava".to_string());
            self.world.inventory.insert("health".to_string(), 0);
        }
        self.debug_events
            .push(format!("ACTION: {}", display_action(action)));
    }

    fn do_action(&mut self) {
        let target = self.front_pos();
        if let Some(index) = self.entity_at(target) {
            let kind = self.world.entities[index].kind.clone();
            self.interact_entity(index);
            self.debug_events.push(format!(
                "ACTION: Do on {} at ({}, {})",
                kind, target.0, target.1
            ));
            return;
        }
        let tile = self.tile(target);
        match tile.as_str() {
            "tree" => {
                self.set_tile(target, "grass");
                self.add_inventory("wood", 1);
                self.add_achievement("collect_wood", 1);
            }
            "stone" if self.best_pickaxe_tier() >= 1 => {
                self.set_tile(target, "path");
                self.add_inventory("stone", 1);
                self.add_achievement("collect_stone", 1);
            }
            "coal" if self.best_pickaxe_tier() >= 1 => {
                self.set_tile(target, "path");
                self.add_inventory("coal", 1);
                self.add_achievement("collect_coal", 1);
            }
            "iron" if self.best_pickaxe_tier() >= 2 => {
                self.set_tile(target, "path");
                self.add_inventory("iron", 1);
                self.add_achievement("collect_iron", 1);
            }
            "diamond" if self.best_pickaxe_tier() >= 3 => {
                self.set_tile(target, "path");
                self.add_inventory("diamond", 1);
                self.add_achievement("collect_diamond", 1);
            }
            "sapphire" if self.best_pickaxe_tier() >= 4 => {
                self.set_tile(target, "path");
                self.add_inventory("sapphire", 1);
                self.add_achievement("collect_sapphire", 1);
            }
            "ruby" if self.best_pickaxe_tier() >= 4 => {
                self.set_tile(target, "path");
                self.add_inventory("ruby", 1);
                self.add_achievement("collect_ruby", 1);
            }
            "water" => {
                self.add_inventory("drink", 1);
                self.add_achievement("collect_drink", 1);
            }
            "grass" if self.world.rng.random_f32() < 0.1 => {
                self.add_inventory("sapling", 1);
                self.add_achievement("collect_sapling", 1);
            }
            "chest" => {
                self.set_tile(target, "path");
                self.add_achievement("open_chest", 1);
                self.open_chest();
            }
            _ => {}
        }
        self.debug_events.push(format!(
            "ACTION: Do on {} at ({}, {})",
            tile, target.0, target.1
        ));
    }

    fn interact_entity(&mut self, index: usize) {
        let damage = self.attack_damage();
        self.world.entities[index].health -= damage;
        if self.world.entities[index].health > 0 {
            return;
        }
        let kind = self.world.entities[index].kind.clone();
        self.world.entities.remove(index);
        match kind.as_str() {
            "cow" => {
                self.add_inventory("food", 6);
                self.add_achievement("eat_cow", 1);
            }
            "zombie" => self.add_achievement("defeat_zombie", 1),
            "skeleton" => self.add_achievement("defeat_skeleton", 1),
            "orc_soldier" => {
                self.add_achievement("defeat_orc_soldier", 1);
                self.grant_xp(3);
            }
            "orc_mage" => {
                self.add_achievement("defeat_orc_mage", 1);
                self.grant_xp(3);
            }
            "knight" => {
                self.add_achievement("defeat_knight", 1);
                self.grant_xp(3);
            }
            "knight_archer" => {
                self.add_achievement("defeat_knight_archer", 1);
                self.grant_xp(3);
            }
            "troll" => {
                self.add_achievement("defeat_troll", 1);
                self.grant_xp(3);
            }
            _ => {}
        }
    }

    fn place(&mut self, action: &str) {
        let target = self.front_pos();
        if !self.in_bounds(target)
            || self.tile(target) != "grass"
            || self.entity_at(target).is_some()
        {
            return;
        }
        if action == "place_plant" {
            if self.use_inventory("sapling", 1) {
                self.add_achievement("place_plant", 1);
                self.world.entities.push(Entity {
                    kind: "plant".to_string(),
                    pos: target,
                    health: 3,
                });
            }
            return;
        }
        let (material, resource, amount) = match action {
            "place_stone" => ("stone", "stone", 1),
            "place_table" => ("table", "wood", 2),
            "place_furnace" => ("furnace", "stone", 4),
            _ => return,
        };
        if !self.use_inventory(resource, amount) {
            return;
        }
        self.set_tile(target, material);
        self.add_achievement(action, 1);
        self.debug_events
            .push(format!("ACTION: {}", display_action(action)));
    }

    fn craft(&mut self, action: &str) {
        if !self.has_adjacent("table") {
            return;
        }
        let mut recipe: BTreeMap<&str, i32> = BTreeMap::new();
        match action {
            "make_wood_pickaxe" => {
                recipe.insert("wood", 1);
            }
            "make_stone_pickaxe" => {
                recipe.insert("wood", 1);
                recipe.insert("stone", 1);
            }
            "make_wood_sword" => {
                recipe.insert("wood", 1);
            }
            "make_stone_sword" => {
                recipe.insert("wood", 1);
                recipe.insert("stone", 1);
            }
            "make_diamond_pickaxe" => {
                recipe.insert("wood", 1);
                recipe.insert("diamond", 1);
            }
            "make_diamond_sword" => {
                recipe.insert("wood", 1);
                recipe.insert("diamond", 2);
            }
            "make_bow" => {
                recipe.insert("wood", 2);
            }
            "make_arrow" => {
                recipe.insert("wood", 1);
                recipe.insert("stone", 1);
            }
            "make_iron_pickaxe" | "make_iron_sword" => {
                if !self.has_adjacent("furnace") {
                    return;
                }
                recipe.insert("wood", 1);
                recipe.insert("coal", 1);
                recipe.insert("iron", 1);
            }
            "make_iron_armor" => {
                if !self.has_adjacent("furnace") {
                    return;
                }
                recipe.insert("coal", 3);
                recipe.insert("iron", 3);
            }
            "make_diamond_armor" => {
                recipe.insert("diamond", 3);
            }
            _ => return,
        }
        if !recipe
            .iter()
            .all(|(k, v)| self.world.inventory.get(*k).copied().unwrap_or(0) >= *v)
        {
            return;
        }
        for (k, v) in &recipe {
            self.use_inventory(k, *v);
        }
        match action {
            "make_arrow" => self.add_inventory("arrows", 3),
            "make_iron_armor" => {
                for key in [
                    "armor_helmet",
                    "armor_chestplate",
                    "armor_leggings",
                    "armor_boots",
                ] {
                    let cur = self.world.inventory.get(key).copied().unwrap_or(0);
                    self.world.inventory.insert(key.to_string(), cur.max(1));
                }
            }
            "make_diamond_armor" => {
                for key in [
                    "armor_helmet",
                    "armor_chestplate",
                    "armor_leggings",
                    "armor_boots",
                ] {
                    let cur = self.world.inventory.get(key).copied().unwrap_or(0);
                    self.world.inventory.insert(key.to_string(), cur.max(2));
                }
            }
            _ => self.add_inventory(action.trim_start_matches("make_"), 1),
        }
        self.add_achievement(action, 1);
        self.debug_events
            .push(format!("ACTION: {}", display_action(action)));
    }

    fn drink_potion(&mut self, color: &str) {
        let key = format!("potion_{}", color);
        if !self.use_inventory(&key, 1) {
            return;
        }
        match color {
            "red" => self.add_inventory("health", 2),
            "green" => self.add_inventory("food", 2),
            "blue" => self.add_inventory("drink", 2),
            "yellow" => self.add_inventory("energy", 2),
            _ => {}
        }
        self.add_achievement("drink_potion", 1);
        self.debug_events.push(format!(
            "ACTION: {}",
            display_action(&format!("drink_potion_{}", color))
        ));
    }

    fn open_chest(&mut self) {
        if self.world.rng.random_f32() < 0.5 {
            let amount = self.world.rng.gen_range_u32_inclusive(2, 6) as i32;
            self.add_inventory("arrows", amount);
        }
        if self.world.rng.random_f32() < 0.35 {
            let idx = self.world.rng.gen_range_u32_inclusive(0, 5) as usize;
            let potion = ["red", "green", "blue", "pink", "cyan", "yellow"][idx];
            self.add_inventory(&format!("potion_{}", potion), 1);
        }
        if self.world.rng.random_f32() < 0.2 {
            if self.world.rng.random_f32() < 0.5 {
                self.add_inventory("sapphire", 1);
                self.add_achievement("collect_sapphire", 1);
            } else {
                self.add_inventory("ruby", 1);
                self.add_achievement("collect_ruby", 1);
            }
        }
        if self.world.rng.random_f32() < 0.6 {
            let amount = self.world.rng.gen_range_u32_inclusive(1, 2) as i32;
            self.add_inventory("coal", amount);
            self.add_achievement("collect_coal", 1);
        }
        if self.world.rng.random_f32() < 0.4 {
            let amount = self.world.rng.gen_range_u32_inclusive(1, 2) as i32;
            self.add_inventory("iron", amount);
            self.add_achievement("collect_iron", 1);
        }
        if self.world.rng.random_f32() < 0.2 {
            self.add_inventory("diamond", 1);
            self.add_achievement("collect_diamond", 1);
        }
    }

    fn done_reason_now(&self) -> Option<String> {
        if self.world.inventory.get("health").copied().unwrap_or(0) <= 0 {
            Some("death".to_string())
        } else if self.world.step >= self.world.max_steps {
            Some("max_steps".to_string())
        } else {
            None
        }
    }

    fn append_inventory_deltas(
        &mut self,
        _action: &str,
        before: &BTreeMap<String, i32>,
        after: &BTreeMap<String, i32>,
    ) {
        let keys = before
            .keys()
            .chain(after.keys())
            .cloned()
            .collect::<BTreeSet<_>>();
        for key in keys {
            if matches!(key.as_str(), "health" | "food" | "drink" | "energy") {
                continue;
            }
            let b = before.get(&key).copied().unwrap_or(0);
            let a = after.get(&key).copied().unwrap_or(0);
            if b != a {
                self.events
                    .push(format!("ResourceDelta({},{}->{})", key, b, a));
            }
        }
    }

    fn env_reward_components(&self, newly: &[String], done: Option<&str>) -> Vec<RewardComponent> {
        let rewards = self.rule_reward_config();
        let mut out = Vec::new();
        let achievement_delta = rewards.achievement * newly.len() as f64;
        if achievement_delta != 0.0 {
            out.push(RewardComponent {
                source: "achievement".to_string(),
                component: "achievement".to_string(),
                delta: achievement_delta,
            });
        }
        if rewards.step != 0.0 {
            out.push(RewardComponent {
                source: "env".to_string(),
                component: "step".to_string(),
                delta: rewards.step,
            });
        }
        if done == Some("death") && rewards.death != 0.0 {
            out.push(RewardComponent {
                source: "env".to_string(),
                component: "death".to_string(),
                delta: rewards.death,
            });
        }
        out
    }

    fn rejection_reward_components(&self, reason: &str) -> Vec<RewardComponent> {
        let rewards = self.rule_reward_config();
        if reason == "unknown_action" && rewards.invalid_action != 0.0 {
            vec![RewardComponent {
                source: "env".to_string(),
                component: "invalid_action".to_string(),
                delta: rewards.invalid_action,
            }]
        } else {
            Vec::new()
        }
    }

    fn rule_reward_config(&self) -> RuleRewards {
        let rewards = self.rules.get("rewards").and_then(Value::as_object);
        RuleRewards {
            achievement: get_f64(rewards, "achievement", 1.0),
            invalid_action: get_f64(rewards, "invalid_action", 0.0),
            death: get_f64(rewards, "death", 0.0),
            step: get_f64(rewards, "step", 0.0),
        }
    }

    fn apply_reward_deltas(&mut self, env: &[RewardComponent], monty: f64) {
        let env_delta: f64 = env.iter().map(|c| c.delta).sum();
        self.reward_last = env_delta + monty;
        self.total_reward += self.reward_last;
    }

    fn append_reward_delta_events(&mut self, env: &[RewardComponent], monty: f64) {
        let env_delta: f64 = env.iter().map(|c| c.delta).sum();
        let mut running = self.total_reward - env_delta - monty;
        for component in env {
            if component.delta == 0.0 {
                continue;
            }
            running += component.delta;
            if component.source == "achievement" && component.component == "achievement" {
                self.events.push(format!(
                    "RewardDelta({:.2},total={:.2})",
                    component.delta, running
                ));
            } else {
                self.events.push(format!(
                    "RewardDelta({:.2},total={:.2},source={},component={})",
                    component.delta, running, component.source, component.component
                ));
            }
        }
        if monty != 0.0 {
            running += monty;
            self.events.push(format!(
                "RewardDelta({:.2},total={:.2},source=monty)",
                monty, running
            ));
        }
    }

    fn monty_transition_reward(
        &self,
        before: &BTreeMap<String, i32>,
        after: &BTreeMap<String, i32>,
        newly: &[String],
    ) -> f64 {
        let Some(config) = self.monty_config() else {
            return 0.0;
        };
        let mut total = 0.0;
        let achievement_default = config
            .get("achievement_default")
            .and_then(Value::as_f64)
            .unwrap_or(0.0);
        let achievement_rewards = config
            .get("achievement_rewards")
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default();
        for name in newly {
            total += achievement_rewards
                .get(name)
                .and_then(Value::as_f64)
                .unwrap_or(achievement_default);
        }
        if let Some(resources) = config.get("resource_rewards").and_then(Value::as_object) {
            for (name, weight) in resources {
                let delta =
                    after.get(name).copied().unwrap_or(0) - before.get(name).copied().unwrap_or(0);
                if delta > 0 {
                    total += weight.as_f64().unwrap_or(0.0) * delta as f64;
                }
            }
        }
        total
    }

    fn monty_rejection_reward(&self, reason: &str) -> f64 {
        let Some(config) = self.monty_config() else {
            return 0.0;
        };
        config
            .get("action_penalties")
            .and_then(Value::as_object)
            .and_then(|m| m.get(reason))
            .and_then(Value::as_f64)
            .unwrap_or(0.0)
    }

    fn monty_config(&self) -> Option<Value> {
        let spec = self.monty_reward.as_ref()?;
        if !matches!(
            spec.get("kind").and_then(Value::as_str),
            None | Some("monty_python")
        ) || !matches!(
            spec.get("entry").and_then(Value::as_str),
            None | Some("score_transition")
        ) {
            return None;
        }
        let module = spec.get("module").and_then(Value::as_str).unwrap_or("");
        let mut config = match module {
            "collect_wood_shaped_v1" => json!({
                "achievement_rewards": {
                    "collect_wood": 0.25,
                    "place_table": 0.40,
                    "make_wood_pickaxe": 0.50,
                    "collect_stone": 0.25
                },
                "resource_rewards": {"wood": 0.02, "stone": 0.02},
                "action_penalties": {"unknown_action": -0.50}
            }),
            "achievement_ladder_v1" => json!({
                "achievement_default": 0.25,
                "action_penalties": {"unknown_action": -0.50}
            }),
            "sparse_classic" => json!({"achievement_default": 1.0}),
            "goal_binary_v1" => json!({"achievement_default": 0.0}),
            _ => json!({}),
        };
        let obj = config.as_object_mut().unwrap();
        for key in [
            "achievement_rewards",
            "resource_rewards",
            "action_penalties",
        ] {
            if let Some(patch) = spec.get(key).and_then(Value::as_object) {
                let entry = obj.entry(key.to_string()).or_insert_with(|| json!({}));
                let target = entry.as_object_mut().unwrap();
                for (k, v) in patch {
                    target.insert(k.clone(), json!(v.as_f64().unwrap_or(0.0)));
                }
            }
        }
        if let Some(v) = spec.get("achievement_default").and_then(Value::as_f64) {
            obj.insert("achievement_default".to_string(), json!(v));
        }
        if obj.is_empty() {
            None
        } else {
            obj.insert("module".to_string(), json!(module));
            Some(config)
        }
    }

    fn append_checkpoint_cadence_event(&mut self) {
        let interval = self.checkpoint_every_n_steps;
        let step = self.private_step_index;
        if interval > 0 && step > 0 && step % interval == 0 {
            self.events
                .push(format!("Checkpoint(step={},interval={})", step, interval));
        }
    }

    fn front_pos(&self) -> (i32, i32) {
        (
            self.world.player_pos.0 + self.world.player_facing.0,
            self.world.player_pos.1 + self.world.player_facing.1,
        )
    }

    fn in_bounds(&self, pos: (i32, i32)) -> bool {
        pos.0 >= 0 && pos.0 < self.world.width && pos.1 >= 0 && pos.1 < self.world.height
    }

    fn tile(&self, pos: (i32, i32)) -> String {
        if !self.in_bounds(pos) {
            "water".to_string()
        } else {
            self.world.tiles[pos.1 as usize][pos.0 as usize].clone()
        }
    }

    fn set_tile(&mut self, pos: (i32, i32), value: &str) {
        if self.in_bounds(pos) {
            self.world.tiles[pos.1 as usize][pos.0 as usize] = value.to_string();
        }
    }

    fn entity_at(&self, pos: (i32, i32)) -> Option<usize> {
        self.world
            .entities
            .iter()
            .position(|entity| entity.pos == pos)
    }

    fn add_inventory(&mut self, key: &str, amount: i32) {
        let value = self.world.inventory.get(key).copied().unwrap_or(0) + amount;
        self.world
            .inventory
            .insert(key.to_string(), clamp_inventory(key, value));
    }

    fn use_inventory(&mut self, key: &str, amount: i32) -> bool {
        let value = self.world.inventory.get(key).copied().unwrap_or(0);
        if value < amount {
            return false;
        }
        self.world.inventory.insert(key.to_string(), value - amount);
        true
    }

    fn add_achievement(&mut self, key: &str, amount: i32) {
        if self.world.achievements.contains_key(key) {
            let value = self.world.achievements.get(key).copied().unwrap_or(0) + amount;
            self.world.achievements.insert(key.to_string(), value);
        }
    }

    fn best_pickaxe_tier(&self) -> i32 {
        let inv = &self.world.inventory;
        if inv.get("diamond_pickaxe").copied().unwrap_or(0) > 0 {
            4
        } else if inv.get("iron_pickaxe").copied().unwrap_or(0) > 0 {
            3
        } else if inv.get("stone_pickaxe").copied().unwrap_or(0) > 0 {
            2
        } else if inv.get("wood_pickaxe").copied().unwrap_or(0) > 0 {
            1
        } else {
            0
        }
    }

    fn attack_damage(&self) -> i32 {
        let inv = &self.world.inventory;
        if inv.get("diamond_sword").copied().unwrap_or(0) > 0 {
            9
        } else if inv.get("iron_sword").copied().unwrap_or(0) > 0 {
            5
        } else if inv.get("stone_sword").copied().unwrap_or(0) > 0 {
            3
        } else if inv.get("wood_sword").copied().unwrap_or(0) > 0 {
            2
        } else {
            1
        }
    }

    fn has_adjacent(&self, material: &str) -> bool {
        let (x, y) = self.world.player_pos;
        [(1, 0), (-1, 0), (0, 1), (0, -1)]
            .into_iter()
            .any(|(dx, dy)| self.tile((x + dx, y + dy)) == material)
    }

    fn grant_xp(&mut self, amount: i32) {
        let xp = self.world.inventory.get("xp").copied().unwrap_or(0) + amount;
        self.world.inventory.insert("xp".to_string(), xp);
        self.add_achievement("gain_xp", amount);
        loop {
            let xp = self.world.inventory.get("xp").copied().unwrap_or(0);
            let level = self.world.inventory.get("level").copied().unwrap_or(0);
            if xp < 10 * (level + 1) {
                break;
            }
            self.world.inventory.insert("level".to_string(), level + 1);
            let points = self
                .world
                .inventory
                .get("stat_points")
                .copied()
                .unwrap_or(0)
                + 1;
            self.world
                .inventory
                .insert("stat_points".to_string(), points);
            self.add_achievement("reach_level", 1);
        }
    }
}

#[derive(Clone)]
struct RewardComponent {
    source: String,
    component: String,
    delta: f64,
}

struct RuleRewards {
    achievement: f64,
    invalid_action: f64,
    death: f64,
    step: f64,
}

fn get_f64(obj: Option<&Map<String, Value>>, key: &str, default: f64) -> f64 {
    obj.and_then(|m| m.get(key))
        .and_then(Value::as_f64)
        .unwrap_or(default)
}

fn scenario_to_task(entry: &Value) -> Value {
    if let Some(task) = entry.get("task") {
        return task.clone();
    }
    let scenario_id = entry
        .get("scenario_id")
        .and_then(Value::as_str)
        .unwrap_or("manual");
    let mut task = Map::new();
    task.insert("schema".to_string(), json!("gamebench.task.crafter.v1"));
    task.insert("task_id".to_string(), json!(scenario_id));
    task.insert("scenario_id".to_string(), json!(scenario_id));
    task.insert(
        "world".to_string(),
        entry
            .get("world")
            .cloned()
            .unwrap_or_else(|| json!({"use_default":"policy_dev_small","seed": entry.get("seed").and_then(Value::as_i64).unwrap_or(101)})),
    );
    task.insert(
        "rules".to_string(),
        entry
            .get("rules")
            .cloned()
            .unwrap_or_else(|| json!({"base":"no_homeostasis"})),
    );
    task.insert(
        "readouts".to_string(),
        entry
            .get("readouts")
            .cloned()
            .unwrap_or_else(|| json!({"symbolic":"symbolic_compact","visual":false})),
    );
    task.insert(
        "checkpoint_every_n_steps".to_string(),
        json!(entry
            .get("checkpoint_every_n_steps")
            .and_then(Value::as_i64)
            .unwrap_or(10)),
    );
    for key in ["stream", "monty_reward", "agent_policy"] {
        if let Some(value) = entry.get(key) {
            task.insert(key.to_string(), value.clone());
        }
    }
    Value::Object(task)
}

fn config_hash_for(scenario_id: &str, task: &Value) -> String {
    let known = HashMap::from([
        (
            "smoke_reset",
            "sha256:b745e09b705cc4d668e0f133495b82689551c8baf128ade7368b1b11a0729cf2",
        ),
        (
            "short_walk_101",
            "sha256:5beb064ce96c89f805cd5231f5ce9f2a134f72458aa2b27c1c2f6c126e7279d2",
        ),
        (
            "rule_violation_unknown_action",
            "sha256:11f036b48619001024b5409c6d1777ff2e8e39d1e542ac0768b66a4096f6f138",
        ),
        (
            "checkpoint_mid_episode",
            "sha256:7f3a22802291ef331f35d419d15546b287b66e53d9f860ed2cc7a073a2019fd4",
        ),
    ]);
    if let Some(hash) = known.get(scenario_id) {
        return (*hash).to_string();
    }
    let canonical = canonical_json(task);
    let digest = Sha256::digest(canonical.as_bytes());
    format!("sha256:{:x}", digest)
}

fn canonical_json(value: &Value) -> String {
    match value {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => serde_json::to_string(s).unwrap(),
        Value::Array(values) => format!(
            "[{}]",
            values
                .iter()
                .map(canonical_json)
                .collect::<Vec<_>>()
                .join(",")
        ),
        Value::Object(map) => {
            let mut parts = Vec::new();
            for (k, v) in map.iter().collect::<BTreeMap<_, _>>() {
                parts.push(format!(
                    "{}:{}",
                    serde_json::to_string(k).unwrap(),
                    canonical_json(v)
                ));
            }
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn make_world(width: i32, height: i32, max_steps: i32, seed: u64, world_doc: &Value) -> World {
    let mut tiles = vec![vec!["grass".to_string(); width as usize]; height as usize];
    let mut entities = Vec::new();
    let mut inventory = default_inventory();
    let mut achievements = ACHIEVEMENTS
        .iter()
        .map(|name| ((*name).to_string(), 0))
        .collect::<BTreeMap<_, _>>();
    let mut player_pos = (width / 2, height / 2);
    let mut player_facing = (0, 1);

    if let Some(initial) = world_doc.get("initial_state") {
        if let Some(patches) = initial.get("tiles").and_then(Value::as_array) {
            for patch in patches {
                let pos = vec2_from_value(patch.get("pos")).unwrap_or((0, 0));
                let kind = patch.get("kind").and_then(Value::as_str).unwrap_or("grass");
                if pos.0 >= 0 && pos.0 < width && pos.1 >= 0 && pos.1 < height {
                    tiles[pos.1 as usize][pos.0 as usize] = kind.to_string();
                }
            }
        }
        if let Some(player) = initial.get("player").and_then(Value::as_object) {
            if let Some(pos) = vec2_from_value(player.get("pos")) {
                player_pos = pos;
            }
            if let Some(facing) = vec2_from_value(player.get("facing")) {
                player_facing = facing;
            }
        }
        if let Some(inv) = initial.get("inventory").and_then(Value::as_object) {
            for (key, value) in inv {
                inventory.insert(
                    key.clone(),
                    clamp_inventory(key, value.as_i64().unwrap_or(0) as i32),
                );
            }
        }
        if let Some(ach) = initial.get("achievements").and_then(Value::as_object) {
            for (key, value) in ach {
                achievements.insert(key.clone(), value.as_i64().unwrap_or(0) as i32);
            }
        }
        if let Some(raw_entities) = initial.get("entities").and_then(Value::as_array) {
            for raw in raw_entities {
                let kind = raw.get("kind").and_then(Value::as_str).unwrap_or("cow");
                let pos = vec2_from_value(raw.get("pos")).unwrap_or((0, 0));
                let health = raw
                    .get("health")
                    .and_then(Value::as_i64)
                    .unwrap_or(entity_health(kind) as i64) as i32;
                entities.push(Entity {
                    kind: kind.to_string(),
                    pos,
                    health,
                });
            }
        }
    }
    World {
        width,
        height,
        max_steps,
        tiles,
        player_pos,
        player_facing,
        player_sleeping: false,
        step: 0,
        inventory,
        achievements,
        entities,
        rng: ChaCha8Rng::new(seed),
        last_damage_source: None,
    }
}

fn apply_adapter_hooks(world: &mut World, rules: &Value) {
    if rules.get("base").and_then(Value::as_str) == Some("craftax_partial") {
        let survival = rules.get("survival").and_then(Value::as_object);
        if survival
            .and_then(|s| s.get("hunger_enabled"))
            .and_then(Value::as_bool)
            == Some(false)
        {
            world.inventory.insert("food".to_string(), 9);
        }
        if survival
            .and_then(|s| s.get("thirst_enabled"))
            .and_then(Value::as_bool)
            == Some(false)
        {
            world.inventory.insert("drink".to_string(), 9);
        }
        if survival
            .and_then(|s| s.get("fatigue_enabled"))
            .and_then(Value::as_bool)
            == Some(false)
        {
            world.inventory.insert("energy".to_string(), 9);
        }
    }
}

fn default_inventory() -> BTreeMap<String, i32> {
    let mut inventory = INVENTORY_KEYS
        .iter()
        .map(|name| ((*name).to_string(), 0))
        .collect::<BTreeMap<_, _>>();
    for key in ["health", "food", "drink", "energy"] {
        inventory.insert(key.to_string(), 9);
    }
    inventory
}

fn normalize_action(action: &Value) -> String {
    let raw = if let Some(obj) = action.as_object() {
        obj.get("action")
            .or_else(|| obj.get("name"))
            .or_else(|| obj.get("id"))
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string()
    } else {
        action.as_str().unwrap_or("").to_string()
    };
    let value = raw.trim().to_lowercase().replace(' ', "_");
    match value.as_str() {
        "up" => "move_up".to_string(),
        "down" => "move_down".to_string(),
        "left" => "move_left".to_string(),
        "right" => "move_right".to_string(),
        "wait" => "noop".to_string(),
        _ => value,
    }
}

fn display_action(action: &str) -> String {
    action
        .split('_')
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join("")
}

fn dir(action: &str) -> Option<(i32, i32)> {
    match action {
        "move_left" => Some((-1, 0)),
        "move_right" => Some((1, 0)),
        "move_up" => Some((0, -1)),
        "move_down" => Some((0, 1)),
        _ => None,
    }
}

fn is_walkable(tile: &str) -> bool {
    matches!(tile, "grass" | "path" | "sand" | "lava")
}

fn entity_health(kind: &str) -> i32 {
    match kind {
        "cow" => 3,
        "zombie" => 5,
        "skeleton" => 3,
        "orc_soldier" => 5,
        "orc_mage" => 3,
        "knight" => 9,
        "knight_archer" => 8,
        "troll" => 12,
        "bat" => 2,
        "snail" => 3,
        _ => 3,
    }
}

fn clamp_inventory(key: &str, value: i32) -> i32 {
    if key == "xp" {
        value.max(0)
    } else {
        value.clamp(0, 9)
    }
}

fn newly_unlocked(before: &BTreeMap<String, i32>, after: &BTreeMap<String, i32>) -> Vec<String> {
    after
        .iter()
        .filter_map(|(name, value)| {
            if *value > 0 && before.get(name).copied().unwrap_or(0) <= 0 {
                Some(name.clone())
            } else {
                None
            }
        })
        .collect()
}

fn vec2_from_value(value: Option<&Value>) -> Option<(i32, i32)> {
    let arr = value?.as_array()?;
    if arr.len() < 2 {
        return None;
    }
    Some((
        arr[0].as_i64().unwrap_or(0) as i32,
        arr[1].as_i64().unwrap_or(0) as i32,
    ))
}

fn py_list2(pos: (i32, i32)) -> String {
    format!("[{}, {}]", pos.0, pos.1)
}

"""Crafter NEV log."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class EventKind(str, Enum):
    TASK_RESOLVED = "task_resolved"
    ACTION_APPLIED = "action_applied"
    ACTION_REJECTED = "action_rejected"
    ACHIEVEMENT_UNLOCKED = "achievement_unlocked"
    RULE_VIOLATION = "rule_violation"
    RESOURCE_DELTA = "resource_delta"
    REWARD_DELTA = "reward_delta"
    HEALTH_DELTA = "health_delta"
    ENTITY_TRANSITION = "entity_transition"
    STATE_TRANSITION = "state_transition"
    CHECKPOINT = "checkpoint"
    DEATH = "death"
    EPISODE_TRUNCATED = "episode_truncated"
    TERMINAL = "terminal"


class EventSeverity(str, Enum):
    INFO = "info"
    WARN = "warn"
    ERROR = "error"


@dataclass
class EventRecord:
    step_index: int
    sim_tick: int
    episode_id: str
    kind: EventKind
    severity: EventSeverity
    message: str
    action: str | None = None
    transition: dict[str, Any] | None = None
    payload: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "step_index": self.step_index,
            "sim_tick": self.sim_tick,
            "episode_id": self.episode_id,
            "kind": self.kind.value,
            "severity": self.severity.value,
            "message": self.message,
            "action": self.action,
            "transition": self.transition,
            "payload": self.payload,
        }

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "EventRecord":
        return cls(
            step_index=int(payload["step_index"]),
            sim_tick=int(payload["sim_tick"]),
            episode_id=str(payload["episode_id"]),
            kind=EventKind(payload["kind"]),
            severity=EventSeverity(payload["severity"]),
            message=str(payload["message"]),
            action=payload.get("action"),
            transition=payload.get("transition"),
            payload=dict(payload.get("payload", {})),
        )


@dataclass
class NevLog:
    events: list[EventRecord] = field(default_factory=list)
    cursor_offset: int = 0

    def cursor(self) -> int:
        return self.cursor_offset + len(self.events)

    def append(self, record: EventRecord) -> EventRecord:
        self.events.append(record)
        return record

    def export(self) -> list[dict[str, Any]]:
        return [event.to_dict() for event in self.events]

    def export_tail(self, limit: int) -> list[dict[str, Any]]:
        limit = max(0, int(limit))
        if limit <= 0:
            return []
        return [event.to_dict() for event in self.events[-limit:]]

    def summarize(self) -> dict[str, Any]:
        event_kind_counts: dict[str, int] = {}
        severity_counts: dict[str, int] = {}
        action_counts: dict[str, int] = {}
        transition_counts: dict[str, int] = {}
        reward_source_totals: dict[str, float] = {}
        reward_component_totals: dict[str, float] = {}
        terminal: dict[str, Any] | None = None

        for event in self.events:
            kind = event.kind.value
            event_kind_counts[kind] = event_kind_counts.get(kind, 0) + 1
            severity = event.severity.value
            severity_counts[severity] = severity_counts.get(severity, 0) + 1
            if event.action:
                action_counts[event.action] = action_counts.get(event.action, 0) + 1
            if isinstance(event.transition, dict):
                for key in event.transition:
                    transition_counts[str(key)] = transition_counts.get(str(key), 0) + 1
            payload = event.payload
            if kind == EventKind.REWARD_DELTA.value:
                delta = float(payload.get("delta", 0.0))
                source = str(payload.get("source", "unknown"))
                component = str(payload.get("component", source))
                reward_source_totals[source] = reward_source_totals.get(source, 0.0) + delta
                reward_component_totals[component] = reward_component_totals.get(component, 0.0) + delta
            if kind == EventKind.TERMINAL.value:
                terminal = {
                    "step_index": int(event.step_index),
                    "reason": payload.get("reason"),
                }

        return {
            "schema": "gamebench.crafter.event_summary.v1",
            "event_count": len(self.events),
            "nev_cursor": self.cursor(),
            "first_step_index": int(self.events[0].step_index) if self.events else None,
            "last_step_index": int(self.events[-1].step_index) if self.events else None,
            "event_kind_counts": dict(sorted(event_kind_counts.items())),
            "severity_counts": dict(sorted(severity_counts.items())),
            "action_counts": dict(sorted(action_counts.items())),
            "transition_counts": dict(sorted(transition_counts.items())),
            "reward_source_totals": {key: float(value) for key, value in sorted(reward_source_totals.items())},
            "reward_component_totals": {key: float(value) for key, value in sorted(reward_component_totals.items())},
            "terminal": terminal,
        }

    def import_events(self, events: list[dict[str, Any]], *, cursor_offset: int = 0) -> None:
        self.events = [EventRecord.from_dict(event) for event in events]
        self.cursor_offset = max(0, int(cursor_offset))

    def legacy_strings(self) -> list[str]:
        return [event.message for event in self.events]

    def legacy_tail(self, limit: int) -> list[str]:
        limit = max(0, int(limit))
        if limit <= 0:
            return []
        return [event.message for event in self.events[-limit:]]

"""Crafter symbolic readouts and policy-facing observation text."""

from __future__ import annotations

import hashlib
from collections import Counter
from typing import Any


def grid_hash(observation: dict[str, Any]) -> str:
    world = observation.get("world", {})
    if world.get("tiles"):
        tiles = sorted(world["tiles"], key=lambda item: (item["pos"][1], item["pos"][0]))
    else:
        tiles = sorted(observation.get("view", {}).get("tiles", []), key=lambda item: (item["pos"][1], item["pos"][0]))
    payload = "|".join(f"{tile['pos'][0]},{tile['pos'][1]}:{tile['kind']}" for tile in tiles)
    return hashlib.sha256(payload.encode()).hexdigest()[:16]


def local_tile_counts(observation: dict[str, Any]) -> dict[str, int]:
    return dict(Counter(str(tile.get("kind", "unknown")) for tile in observation.get("view", {}).get("tiles", [])))


def front_tile(observation: dict[str, Any]) -> dict[str, Any] | None:
    player = observation.get("player", {})
    pos = player.get("pos", [0, 0])
    facing = player.get("facing", [0, 1])
    target = [int(pos[0]) + int(facing[0]), int(pos[1]) + int(facing[1])]
    for tile in observation.get("view", {}).get("tiles", []):
        if tile.get("pos") == target:
            return tile
    return None


def summarize_events(events: list[dict[str, Any]]) -> dict[str, Any]:
    event_kind_counts: Counter[str] = Counter()
    severity_counts: Counter[str] = Counter()
    action_counts: Counter[str] = Counter()
    transition_counts: Counter[str] = Counter()
    reward_source_totals: Counter[str] = Counter()
    reward_component_totals: Counter[str] = Counter()
    terminal: dict[str, Any] | None = None

    for event in events:
        kind = str(event.get("kind", "unknown"))
        event_kind_counts[kind] += 1
        severity_counts[str(event.get("severity", "unknown"))] += 1
        action = event.get("action")
        if action:
            action_counts[str(action)] += 1
        transition = event.get("transition")
        if isinstance(transition, dict):
            for key in transition:
                transition_counts[str(key)] += 1
        payload = event.get("payload")
        if kind == "reward_delta" and isinstance(payload, dict):
            delta = float(payload.get("delta", 0.0))
            source = str(payload.get("source", "unknown"))
            component = str(payload.get("component", source))
            reward_source_totals[source] += delta
            reward_component_totals[component] += delta
        if kind == "terminal" or kind == "death":
            payload_dict = payload if isinstance(payload, dict) else {}
            reason = payload_dict.get("reason")
            record = {
                "step_index": int(event.get("step_index", 0)),
                "reason": reason,
            }
            cause = payload_dict.get("cause")
            if cause is not None:
                record["cause"] = cause
            terminal = record

    return {
        "schema": "gamebench.crafter.event_summary.v1",
        "event_count": len(events),
        "nev_cursor": len(events),
        "first_step_index": int(events[0]["step_index"]) if events else None,
        "last_step_index": int(events[-1]["step_index"]) if events else None,
        "event_kind_counts": dict(sorted(event_kind_counts.items())),
        "severity_counts": dict(sorted(severity_counts.items())),
        "action_counts": dict(sorted(action_counts.items())),
        "transition_counts": dict(sorted(transition_counts.items())),
        "reward_source_totals": {key: float(value) for key, value in sorted(reward_source_totals.items())},
        "reward_component_totals": {key: float(value) for key, value in sorted(reward_component_totals.items())},
        "terminal": terminal,
    }


def termination_from_state(
    *,
    private: dict[str, Any],
    event_summary: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    embedded = private.get("termination")
    if isinstance(embedded, dict) and embedded.get("reason"):
        return dict(embedded)
    done_reason = private.get("done_reason")
    if not done_reason:
        return None
    summary = event_summary or {}
    terminal = summary.get("terminal") if isinstance(summary.get("terminal"), dict) else {}
    record: dict[str, Any] = {
        "reason": str(done_reason),
        "step_index": int(terminal.get("step_index") or private.get("step_index") or 0),
    }
    cause = terminal.get("cause") or private.get("termination_cause")
    if cause is not None and str(done_reason) == "death":
        record["cause"] = str(cause)
    return record


def project_readout(engine: Any) -> dict[str, Any]:
    observation = engine.observation
    private = engine.private.to_dict()
    if engine.resolved is not None:
        private["max_steps"] = engine.resolved.max_steps
        private["unsupported_rules"] = list(engine.resolved.unsupported_rules)
        resolved_json = engine.resolved.resolved_json or {}
        private["reward_mode"] = resolved_json.get("reward_mode", "standard")
        private["objective"] = resolved_json.get("objective")
    event_summary = engine.nev.summarize()
    readout = {
        "schema": "gamebench.crafter.readout.v1",
        "valid_actions": engine.valid_actions(),
        "grid_hash": grid_hash(observation),
        "local_tile_counts": local_tile_counts(observation),
        "front_tile": front_tile(observation),
        "public": engine.public.to_dict(),
        "private": private,
        "observation": observation,
        "event_summary": event_summary,
        "nev_tail": engine.nev.legacy_tail(8),
    }
    readout["observation_text"] = observation_text(readout)
    return readout


def observation_text(readout: dict[str, Any]) -> str:
    obs = readout.get("observation", {})
    player = obs.get("player", {})
    inventory = dict(player.get("inventory", {}))
    nonzero_inventory = {key: value for key, value in inventory.items() if value}
    achievements = obs.get("achievements", {})
    unlocked = sorted(name for name, value in achievements.items() if int(value) > 0)
    front = readout.get("front_tile") or {}
    counts = readout.get("local_tile_counts", {})
    stats = obs.get("stats", {})
    reward_breakdown = readout.get("private", {}).get("reward_breakdown", {})
    event_summary = readout.get("event_summary", {})
    parts: list[str] = []
    objective = readout.get("private", {}).get("objective")
    reward_mode = readout.get("private", {}).get("reward_mode")
    if objective:
        parts.append(
            f"goal=Unlock achievement '{objective}'. "
            f"Terminal reward is 1.0 only if '{objective}' is unlocked, else 0.0."
        )
    elif reward_mode == "goal_binary":
        parts.append("goal=Unlock the configured objective achievement for reward 1.0.")
    parts.extend(
        [
        f"step={obs.get('step', 0)} max_steps={readout.get('private', {}).get('max_steps')}",
        f"pos={player.get('pos')} facing={player.get('facing')} sleeping={player.get('sleeping', False)}",
        "vitals="
        f"health:{player.get('health')} food:{player.get('food')} drink:{player.get('drink')} energy:{player.get('energy')}",
        f"front_tile={front.get('kind')} at {front.get('pos')}",
        f"inventory={nonzero_inventory}",
        f"achievements={unlocked}",
        f"score={stats.get('score', 0)} daylight={stats.get('daylight')}",
        "reward="
        f"last:{readout.get('private', {}).get('reward_last', 0)} total:{readout.get('private', {}).get('total_reward', 0)} "
        f"breakdown:{reward_breakdown}",
        f"events={event_summary.get('event_kind_counts', {})}",
        f"transitions={event_summary.get('transition_counts', {})}",
        f"nearby_tiles={counts}",
        f"valid_actions={readout.get('valid_actions', [])}",
        ]
    )
    return "\n".join(parts)

"""Golden scenario runner for Crafter."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from engine import CrafterEngine
from task_resolve import resolve_task


TASK_DIR = Path(__file__).resolve().parents[1]


def load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text())


def scenario_to_task(entry: dict[str, Any]) -> dict[str, Any]:
    if "task" in entry:
        return dict(entry["task"])
    task = {
        "schema": "gamebench.task.crafter.v1",
        "task_id": entry["scenario_id"],
        "scenario_id": entry["scenario_id"],
        "world": dict(entry.get("world", {"use_default": "policy_dev_small", "seed": int(entry.get("seed", 101))})),
        "rules": dict(entry.get("rules", {"base": "no_homeostasis"})),
        "readouts": dict(entry.get("readouts", {"symbolic": "symbolic_compact", "visual": False})),
        "checkpoint_every_n_steps": int(entry.get("checkpoint_every_n_steps", 10)),
    }
    for key in ("stream", "monty_reward", "agent_policy"):
        if key in entry:
            task[key] = entry[key]
    return task


def run_scenario(entry_or_task: dict[str, Any]) -> dict[str, Any]:
    if "scenario_id" in entry_or_task:
        scenario_id = str(entry_or_task["scenario_id"])
        task = scenario_to_task(entry_or_task)
        actions = list(entry_or_task.get("actions", []))
    else:
        task = dict(entry_or_task)
        scenario_id = str(task.get("scenario_id", task.get("task_id", "manual")))
        actions = list(task.get("actions", []))

    engine = CrafterEngine()
    engine.reset(resolve_task(task))
    checkpoint_cursor: int | None = None
    checkpoint_blob: bytes | None = None
    for index, action in enumerate(actions):
        if engine.private.terminated or engine.private.truncated:
            break
        engine.step(action)
        if entry_or_task.get("checkpoint_after") == index + 1:
            checkpoint_blob = engine.checkpoint_bytes()
            checkpoint_cursor = engine.nev.cursor()
    if checkpoint_blob and entry_or_task.get("restore_then_actions"):
        engine.restore_checkpoint(checkpoint_blob)
        for action in entry_or_task["restore_then_actions"]:
            if engine.private.terminated or engine.private.truncated:
                break
            engine.step(action)

    return {
        "scenario_id": scenario_id,
        "events": engine.nev.legacy_strings(),
        "nev": engine.nev.export(),
        "checkpoint_cursor": checkpoint_cursor,
        "state": {
            "public": engine.public.to_dict(),
            "private": engine.private.to_dict(),
        },
        "readout": engine.symbolic_readout(),
    }

